package basics;

public class MultiplicationTable {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
	      int number = 12;
	        int i = 1;
	    	System.out.println("Multiplicaton Table of 2");
	        do {
	        
	            System.out.println(i + " x " + number + " = " + (i * number));
	            i++;
	        } while (i <= 10);

	}

}
